// ── 💧 parche-culling-agua · BUG-FLUID6 (Desarrollo Desacoplado) ───────────────────────────
//
// Corrige la desaparición indebida de las caras de columnas/masas de agua cuando tienen al lado
// una estructura fina con huecos (verja, escalera, flores, marcos, etc.).
//
// Mandos en vivo:
//   game.parcheCullingAgua.on()       · Activar parche en caliente
//   game.parcheCullingAgua.off()      · Desactivar y restaurar mcMeshChunk original (A/B)
//   game.parcheCullingAgua.estado()   · Informe de estado y chunks remallados
//
(() => {
  'use strict';

  function esMaciza(key){
    if(!key || typeof mc === 'undefined' || !mc.structs) return false;
    const base = (typeof mcClaveBase === 'function') ? mcClaveBase(key) : key.replace(/@\d{1,2}$/,'');
    const rec = mc.structs[base];
    if(!rec) return false;
    return !!(rec.blockLike || (rec.pielCubre && !rec.conCaras && !rec.translucido));
  }

  function envolver(){
    if(window.mcMeshChunk && window.mcMeshChunk._pcaOrig) return;
    const orig = window.mcMeshChunk;
    if(typeof orig !== 'function'){
      console.warn('parche-culling-agua: no encuentro mcMeshChunk()');
      return;
    }

    // Sobrescribir mcMeshChunk con la versión que valida pielCubre / huecos en estructuras finas
    window.mcMeshChunk = function(cx, cz){
      const dim=mc.dim, gl=mc.gl;
      if(!gl || !mc.grid) return;
      const x0=cx*MC_CHUNK, x1=Math.min(x0+MC_CHUNK, dim.x);
      const z0=cz*MC_CHUNK, z1=Math.min(z0+MC_CHUNK, dim.z);

      const _CACHE_SLOTS = (typeof game !== 'undefined' && game.chunkCacheSlots|0) || 32;
      const _CACHE_STRICT = (typeof game === 'undefined') || game.cacheStrict !== false;
      const chunkKeyEarly = cx+','+cz;
      const chEarly = mc.chunks.get(chunkKeyEarly);
      let _sigCalc = 0, _sigListo = false;
      if(chEarly){
        let sig = (mc.palette.length|0) * 1000003 + (mc.gridGen|0)
                  + (mc.sinCullingFluido ? 7919 : 0) + 17;
        const SS0=mc.sinSombra; if(SS0){ for(let i=0;i<SS0.length;i++) if(SS0[i]) sig=((sig*13 + i*7 + SS0[i])|0); }
        const g0=mc.grid, L0=mc.light, BL0=_CACHE_STRICT ? mc.blockLight : null;
        const NX=dim.x, sxyEarly=NX*dim.y;
        for(let z=z0;z<z1;z++) for(let x=x0;x<x1;x++) for(let y=0;y<dim.y;y++){
          const i=x+y*NX+z*sxyEarly;
          sig = ((sig*31 + g0[i]) | 0);
          if(L0){ sig = ((sig*7 + L0[i]) | 0); }
          if(BL0){ sig = ((sig*11 + BL0[i]) | 0); }
        }
        _sigCalc = sig; _sigListo = true;
        if(chEarly._meshSig === sig){ mc._cacheHits = (mc._cacheHits|0) + 1; return; }
        if(chEarly._cache){
          for(let idx=0; idx<chEarly._cache.length; idx++){
            if(chEarly._cache[idx].sig === sig){
              const slot = chEarly._cache[idx];
              const saliente = {
                sig: chEarly._meshSig, vbo: chEarly.vbo, count: chEarly.count,
                finoVbo: chEarly.finoVbo, finoCount: chEarly.finoCount,
                finoAVbo: chEarly.finoAVbo, finoACount: chEarly.finoACount,
                aabb: chEarly.aabb,
              };
              chEarly._meshSig = slot.sig;
              chEarly.vbo = slot.vbo; chEarly.count = slot.count;
              chEarly.finoVbo = slot.finoVbo; chEarly.finoCount = slot.finoCount;
              chEarly.finoAVbo = slot.finoAVbo; chEarly.finoACount = slot.finoACount;
              chEarly.aabb = slot.aabb;
              chEarly._cache.splice(idx, 1);
              chEarly._cache.push(saliente);
              mc._cacheHits = (mc._cacheHits|0) + 1;
              mcShadowDirty();
              return;
            }
          }
        }
        mc._cacheMisses = (mc._cacheMisses|0) + 1;
        if(chEarly._meshSig !== undefined && chEarly.vbo && chEarly.count>0){
          if(!chEarly._cache) chEarly._cache = [];
          chEarly._cache.push({
            sig: chEarly._meshSig, vbo: chEarly.vbo, count: chEarly.count,
            finoVbo: chEarly.finoVbo, finoCount: chEarly.finoCount,
            finoAVbo: chEarly.finoAVbo, finoACount: chEarly.finoACount,
            aabb: chEarly.aabb,
          });
          while(chEarly._cache.length > _CACHE_SLOTS){
            const ev = chEarly._cache.shift();
            if(ev.vbo) gl.deleteBuffer(ev.vbo);
            if(ev.finoVbo) gl.deleteBuffer(ev.finoVbo);
            if(ev.finoAVbo) gl.deleteBuffer(ev.finoAVbo);
          }
          chEarly.vbo = gl.createBuffer();
          chEarly.finoVbo = null; chEarly.finoCount = 0;
          chEarly.finoAVbo = null; chEarly.finoACount = 0;
        }
        chEarly._meshSig = sig;
      }
      const verts=[];
      const dark=mc.interiorDark, L=mc.light, BL=mc.blockLight;
      let lightLut=null;
      if(dark!==1 && L){
        lightLut=new Float32Array(MC_MAXLIGHT+1);
        for(let lv=0;lv<=MC_MAXLIGHT;lv++) lightLut[lv]=Math.pow(dark,(MC_MAXLIGHT-lv)/MC_MAXLIGHT);
      }
      const SS=mc.sinSombra;
      const GEO=mcTablaFina();
      const finas=[];
      for(let z=z0;z<z1;z++) for(let x=x0;x<x1;x++) for(let y=0;y<dim.y;y++){
        const id=mc.grid[mcIdx(x,y,z)]; if(!id) continue;
        if(GEO && GEO[id]){ finas.push(x,y,z,id); continue; }
        const rects=mc.palette[id]; if(!rects) continue;
        const fluidH = mcGetFluidHeight(x, y, z);
        for(let f=0;f<6;f++){
          const F=MC_FACES[f], d=F.dir;
          const ax=x+d[0], ay=y+d[1], az=z+d[2];
          if(fluidH >= 0.999 && mcTapaCara(ax,ay,az)) continue;
          if(fluidH < 0.999){
            if(f === 1 && y > 0 && mcTapaCara(x, y - 1, z)) continue;
            if(f !== 0 && f !== 1){
              if(mcInside(ax, ay, az)){
                const nId = mc.grid[mcIdx(ax, ay, az)];
                if(nId > 0){
                  const nH = mcGetFluidHeight(ax, ay, az);
                  if(nH >= fluidH) continue;
                }
              }
            }
          }
          const r=rects[F.tex], C=F.corners;
          const ss=SS?(SS[id]|0):0;
          let s=F.s;
          if(lightLut && !(ss&1)){ let lv=MC_MAXLIGHT; if(mcInside(ax,ay,az)){ const li=mcIdx(ax,ay,az); lv=L?L[li]:MC_MAXLIGHT; } s*=lightLut[lv]; }
          s+=2*ss;
          const uv=[[r.u0,r.v0],[r.u1,r.v0],[r.u1,r.v1],[r.u0,r.v1]];
          for(const k of [0,1,2,0,2,3]){
            const c=C[k];
            const vy = y + c[1] * fluidH;
            verts.push(x+c[0], vy, z+c[2], uv[k][0], uv[k][1], s);
          }
        }
      }

      let capC=0, capA=0;
      for(let i=0;i<finas.length;i+=4){ const g=GEO[finas[i+3]]; if(!g) continue; capC+=g.colCount*9; capA+=g.alphaCount*9; }
      const fcol={buf: capC?new Float32Array(capC):null, n:0};
      const falpha={buf: capA?new Float32Array(capA):null, n:0};
      if(finas.length){
        const copia=(src,count,sc,fd,out,ox,oy,oz,fH,ss,tap,refl)=>{
          const scaleH = (typeof fH === 'number' && fH > 0) ? fH : 1.0;
          for(let f=0, nf=count/6; f<nf; f++){
            if(tap && fd && (tap & (1<<fd[f]))) continue;
            const marca = (refl && fd && fd[f]===0) ? 2 : 0;
            let k=1;
            if(lightLut && sc && !(ss&1)){
              const wx=ox+sc[f*3], wy=oy+sc[f*3+1], wz=oz+sc[f*3+2];
              if(mcInside(wx,wy,wz)){ const li=mcIdx(wx,wy,wz); k=lightLut[L?L[li]:MC_MAXLIGHT]; }
            }
            const B=out.buf; let p=out.n;
            for(let v=0;v<6;v++){ const b=(f*6+v)*9;
              B[p]=src[b]+ox; B[p+1]=oy + src[b+1] * scaleH; B[p+2]=src[b+2]+oz;
              B[p+3]=src[b+3]; B[p+4]=src[b+4]; B[p+5]=src[b+5];
              B[p+6]=src[b+6]*k+2*ss; B[p+7]=src[b+7]+marca; B[p+8]=src[b+8]; p+=9; }
            out.n=p;
          }
        };
        const FT = mc.sinCullingFluido ? null : mcTablaFluido();
        // BUG-FLUID6: tapaAlFluido solo devuelve true si el vecino tapa REALMENTE la cara completa
        const tapaAlFluido=(ax,ay,az)=>{
          if(mcTapaCara(ax,ay,az)) return true;
          if(!GEO || !mcInside(ax,ay,az)) return false;
          const nId = mc.grid[mcIdx(ax,ay,az)];
          if(!nId || !GEO[nId] || (FT && FT[nId])) return false;
          const k = mc.blockKey && mc.blockKey[nId];
          return esMaciza(k);
        };
        const tapadasFluido=(x,y,z,id,fH)=>{
          const tipo = FT ? (FT[id]||'') : '';
          if(!tipo) return 0;
          let bits=0;
          for(let f=0;f<6;f++){
            const d=MC_FACES[f].dir, ax=x+d[0], ay=y+d[1], az=z+d[2];
            if(fH>=0.999 ? tapaAlFluido(ax,ay,az) : (f===1 && y>0 && tapaAlFluido(ax,ay,az))){ bits|=1<<f; continue; }
            const nId = mcInside(ax,ay,az) ? mc.grid[mcIdx(ax,ay,az)] : 0;
            if(!nId || (FT[nId]||'') !== tipo) continue;
            if(f<2){ bits|=1<<f; continue; }
            if(mcGetFluidHeight(ax,ay,az) >= fH-1e-6) bits|=1<<f;
          }
          return bits;
        };
        for(let i=0;i<finas.length;i+=4){
          const x=finas[i], y=finas[i+1], z=finas[i+2], id=finas[i+3], g=GEO[id];
          const fH = mcGetFluidHeight(x, y, z);
          const ss = SS?(SS[id]|0):0;
          const tap = tapadasFluido(x,y,z,id,fH);
          const agua = FT ? (FT[id]||'')==='WATER' : false;
          copia(g.colLocal,   g.colCount,   g.colSC,   g.colFD,   fcol,   x,y,z, fH, ss, tap, agua);
          copia(g.alphaLocal, g.alphaCount, g.alphaSC, g.alphaFD, falpha, x,y,z, fH, ss, tap, agua);
        }
      }
      const key=cx+','+cz; let ch=mc.chunks.get(key);
      if(!ch){ ch={vbo:gl.createBuffer(), count:0, finoVbo:null, finoCount:0, finoAVbo:null, finoACount:0}; mc.chunks.set(key,ch); }
      gl.bindBuffer(gl.ARRAY_BUFFER, ch.vbo);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.STATIC_DRAW);
      ch.count=verts.length/6; ch.aabb=[x0,0,z0, x1,dim.y,z1];
      const sube=(vboProp,cntProp,flujo)=>{
        const n=flujo.n/9;
        if(!n){ if(ch[vboProp]) gl.deleteBuffer(ch[vboProp]); ch[vboProp]=null; ch[cntProp]=0; return; }
        if(!ch[vboProp]) ch[vboProp]=gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, ch[vboProp]);
        gl.bufferData(gl.ARRAY_BUFFER, flujo.n===flujo.buf.length?flujo.buf:flujo.buf.subarray(0,flujo.n), gl.STATIC_DRAW);
        ch[cntProp]=n;
      };
      sube('finoVbo','finoCount', fcol); sube('finoAVbo','finoACount', falpha);
      if(!_sigListo){
        let sig = (mc.palette.length|0) * 1000003 + (mc.gridGen|0)
                  + (mc.sinCullingFluido ? 7919 : 0) + 17;
        const strict = (typeof game === 'undefined') || game.cacheStrict !== false;
        const g0=mc.grid, L0=mc.light, BL0=strict ? mc.blockLight : null, NX=dim.x, sxyE2=NX*dim.y;
        for(let z=z0;z<z1;z++) for(let x=x0;x<x1;x++) for(let y=0;y<dim.y;y++){
          const i=x+y*NX+z*sxyE2;
          sig = ((sig*31 + g0[i]) | 0);
          if(L0){ sig = ((sig*7 + L0[i]) | 0); }
          if(BL0){ sig = ((sig*11 + BL0[i]) | 0); }
        }
        ch._meshSig = sig;
      }
      mcShadowDirty();
    };

    window.mcMeshChunk._pcaOrig = orig;
    if(mc.grid) mcMeshAll();
  }

  function desinstalar(){
    if(window.mcMeshChunk && window.mcMeshChunk._pcaOrig){
      window.mcMeshChunk = window.mcMeshChunk._pcaOrig;
      if(mc.grid) mcMeshAll();
    }
  }

  const API = {
    get puesto(){ return !!(window.mcMeshChunk && window.mcMeshChunk._pcaOrig); },
    on(){
      if(!API.puesto) envolver();
      return API.estado();
    },
    off(){
      if(API.puesto) desinstalar();
      return 'parche-culling-agua: motor original restaurado · mcMeshChunk._pcaOrig quitado';
    },
    estado(){
      return '💧 parche-culling-agua · activo=' + API.puesto + ' · BUG-FLUID6 protegido';
    }
  };

  window.game = window.game || {};
  window.game.parcheCullingAgua = API;

  // Autoactivar al ejecutar el snippet
  API.on();
  console.log(API.estado());
  return API;
})();
